import type { OsmFeature } from "osm-api";

export interface Coordinates {
  lat: number;
  lon: number;
}

export interface OverpassRequest {
  version: number;
  generator: string;
  osm3s: {
    timestamp_osm_base: string;
    timestamp_areas_base: string;
    copyright: string;
  };
  elements: OsmFeature[];
}

/** Regions generated by reverse-geocoding-data are of this type*/
export interface GeographicFolderElement {
  type: "geographic";
  name: string;
  /** Id of the translations of the name, matching regionNames() in app */
  nameId?: number;
  /** Bounding box of the region, in degrees */
  bbox?: { x0: number; x1: number; y0: number; y1: number };
}

export type DataJSON = OsmFeature | GeographicFolderElement;

/** One cliff of a region cliffs.json file, keyed by its OSM reference (`w123`) */
export interface CliffPoint {
  /** `n123`, `w123` or `r123` */
  id: string;
  lon: number;
  lat: number;
  name?: string;
}

/** Content of the cliffs.json file of a region, downloaded by the app at high zoom (issue #55) */
export interface RegionCliffs {
  /** ISO date of the OSM data */
  timestamp: string;
  cliffs: CliffPoint[];
}
